import {
  createTable,
  createTableCaption,
  createTableHeader,
  createTableBody,
  createTableFooter,
  createTableRow,
  createTableHead,
  createTableCell,
} from '@/components/ui/table';

// A fábrica devolve a área rolável e a própria tabela
const { wrapper, table } = createTable();

table.appendChild(createTableCaption('Descrição da tabela'));

const cabecalho = createTableHeader();
const linhaCabecalho = createTableRow();
linhaCabecalho.appendChild(createTableHead('Coluna'));   // scope="col" por padrão
cabecalho.appendChild(linhaCabecalho);

const corpo = createTableBody();
const linha = createTableRow();
linha.appendChild(createTableCell('Dado'));
corpo.appendChild(linha);

const rodape = createTableFooter();
const linhaRodape = createTableRow();
linhaRodape.appendChild(createTableCell('Total'));
rodape.appendChild(linhaRodape);

table.append(cabecalho, corpo, rodape);
document.body.appendChild(wrapper);

import {
  createTable,
  createTableCaption,
  createTableHeader,
  createTableBody,
  createTableFooter,
  createTableRow,
  createTableHead,
  createTableCell,
} from '@/components/ui/table';

// The factory returns the scrollable region and the table itself
const { wrapper, table } = createTable();

table.appendChild(createTableCaption('Table description'));

const head = createTableHeader();
const headRow = createTableRow();
headRow.appendChild(createTableHead('Column'));   // scope="col" by default
head.appendChild(headRow);

const body = createTableBody();
const row = createTableRow();
row.appendChild(createTableCell('Data'));
body.appendChild(row);

const foot = createTableFooter();
const footRow = createTableRow();
footRow.appendChild(createTableCell('Total'));
foot.appendChild(footRow);

table.append(head, body, foot);
document.body.appendChild(wrapper);

