encabezado.appendChild(filaEncabezado);

const cuerpo = createTableBody();
const fila = createTableRow();
fila.appendChild(createTableCell('Dato'));
cuerpo.appendChild(fila);

const pie = createTableFooter();
const filaPie = createTableRow();
filaPie.appendChild(createTableCell('Total'));
pie.appendChild(filaPie);

table.append(encabezado, cuerpo, pie);
document.body.appendChild(wrapper);
